export interface ConnectorConfig {
  /** Discord webhook ID from the webhook URL */
  discordWebhookId: string
  /** Discord webhook token from the webhook URL */
  discordWebhookToken: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface AirtableWebhookPayload {
  baseId: string
  tableId: string
  webhookId: string
  payloads: Array<{
    id: string
    createdTime: string
    baseTransactionNumber: number
    tableId: string
    changes: Array<{
      id: string
      changedFields: Record<string, unknown>
    }>
  }>
}

export interface HandleResult {
  messageIds: string[]
}

export async function handle(
  payload: AirtableWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!config.discordWebhookId) throw new Error('Missing required config: discordWebhookId')
  if (!config.discordWebhookToken) throw new Error('Missing required config: discordWebhookToken')

  if (!payload.baseId) throw new Error('Missing required field: baseId')
  if (!payload.webhookId) throw new Error('Missing required field: webhookId')
  if (!payload.payloads || !Array.isArray(payload.payloads)) throw new Error('Missing required field: payloads')

  const fetchFn = config.fetch ?? fetch
  const messageIds: string[] = []

  const discordUrl = `https://discord.com/api/webhooks/${config.discordWebhookId}/${config.discordWebhookToken}?wait=true`

  for (const payloadItem of payload.payloads) {
    if (!payloadItem.createdTime) throw new Error('Missing required field: createdTime in payload')
    if (!payloadItem.changes || !Array.isArray(payloadItem.changes)) throw new Error('Missing required field: changes in payload')

    for (const change of payloadItem.changes) {
      if (!change.id) throw new Error('Missing required field: id in change')
      if (!change.changedFields || typeof change.changedFields !== 'object') throw new Error('Missing required field: changedFields in change')

      const description = Object.entries(change.changedFields)
        .map(([key, value]) => `${key}: ${value}`)
        .join('\n')

      const discordBody = {
        content: `New Airtable record: ${change.id}`,
        embeds: [
          {
            title: payloadItem.createdTime,
            description,
            color: 5763719
          }
        ]
      }

      const response = await fetchFn(discordUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(discordBody)
      })

      if (!response.ok) {
        throw new Error(`Discord webhook request failed: ${response.status} ${response.statusText} at ${discordUrl}`)
      }

      const data = await response.json() as { id: string }
      messageIds.push(data.id)
    }
  }

  return { messageIds }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, AirtableWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      discordWebhookId: '111111111111111111',
      discordWebhookToken: 'test-token',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.messageIds).toEqual(['123456789012345678'])
  })
})

describe('handle', () => {
  it('sends one Discord message per change with correct field mapping', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://discord.com/api/webhooks/wh-id/wh-token?wait=true')
      expect(req.json).toEqual({
        content: 'New Airtable record: recXXXXXXXXXXXXXX',
        embeds: [{
          title: '2023-04-10T12:34:56.000Z',
          description: 'Field1: value1\nField2: value2',
          color: 5763719
        }]
      })
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload: AirtableWebhookPayload = {
      baseId: 'appXXXXXXXXXXXXXX',
      tableId: 'tblXXXXXXXXXXXXXX',
      webhookId: 'whXXXXXXXXXXXXXX',
      payloads: [{
        id: 'palXXXXXXXXXXXXXX',
        createdTime: '2023-04-10T12:34:56.000Z',
        baseTransactionNumber: 123,
        tableId: 'tblXXXXXXXXXXXXXX',
        changes: [{
          id: 'recXXXXXXXXXXXXXX',
          changedFields: { Field1: 'value1', Field2: 'value2' }
        }]
      }]
    }

    const result = await handle(payload, {
      discordWebhookId: 'wh-id',
      discordWebhookToken: 'wh-token',
      fetch
    })

    expect(result.messageIds).toEqual(['123456789012345678'])
    expect(calls).toHaveLength(1)
  })

  it('includes webhook ID and token in URL for auth', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))

    await handle({
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1',
      payloads: [{
        id: 'pal1',
        createdTime: '2023-01-01T00:00:00.000Z',
        baseTransactionNumber: 1,
        tableId: 'tbl1',
        changes: [{ id: 'rec1', changedFields: { A: '1' } }]
      }]
    }, {
      discordWebhookId: 'my-webhook-id',
      discordWebhookToken: 'my-webhook-token',
      fetch
    })

    expect(calls[0].url).toBe('https://discord.com/api/webhooks/my-webhook-id/my-webhook-token?wait=true')
  })

  it('throws when discordWebhookId is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1',
      payloads: [{ id: 'pal1', createdTime: '2023-01-01T00:00:00.000Z', baseTransactionNumber: 1, tableId: 'tbl1', changes: [{ id: 'rec1', changedFields: {} }] }]
    }, { discordWebhookToken: 'token', fetch } as ConnectorConfig)).rejects.toThrow('Missing required config: discordWebhookId')
  })

  it('throws when discordWebhookToken is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1',
      payloads: [{ id: 'pal1', createdTime: '2023-01-01T00:00:00.000Z', baseTransactionNumber: 1, tableId: 'tbl1', changes: [{ id: 'rec1', changedFields: {} }] }]
    }, { discordWebhookId: 'id', fetch } as ConnectorConfig)).rejects.toThrow('Missing required config: discordWebhookToken')
  })

  it('throws when payload.baseId is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      tableId: 'tbl1',
      webhookId: 'wh1',
      payloads: [{ id: 'pal1', createdTime: '2023-01-01T00:00:00.000Z', baseTransactionNumber: 1, tableId: 'tbl1', changes: [{ id: 'rec1', changedFields: {} }] }]
    } as unknown as AirtableWebhookPayload, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })).rejects.toThrow('Missing required field: baseId')
  })

  it('throws when payload.webhookId is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      baseId: 'app1',
      tableId: 'tbl1',
      payloads: [{ id: 'pal1', createdTime: '2023-01-01T00:00:00.000Z', baseTransactionNumber: 1, tableId: 'tbl1', changes: [{ id: 'rec1', changedFields: {} }] }]
    } as unknown as AirtableWebhookPayload, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })).rejects.toThrow('Missing required field: webhookId')
  })

  it('throws when payload.payloads is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1'
    } as unknown as AirtableWebhookPayload, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })).rejects.toThrow('Missing required field: payloads')
  })

  it('throws when payload item createdTime is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1',
      payloads: [{ id: 'pal1', baseTransactionNumber: 1, tableId: 'tbl1', changes: [{ id: 'rec1', changedFields: {} }] }]
    } as unknown as AirtableWebhookPayload, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })).rejects.toThrow('Missing required field: createdTime in payload')
  })

  it('throws when payload item changes is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1',
      payloads: [{ id: 'pal1', createdTime: '2023-01-01T00:00:00.000Z', baseTransactionNumber: 1, tableId: 'tbl1' }]
    } as unknown as AirtableWebhookPayload, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })).rejects.toThrow('Missing required field: changes in payload')
  })

  it('throws when change id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1',
