    } as unknown as AirtableWebhookPayload, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })).rejects.toThrow('Missing required field: id in change')
  })

  it('throws when change changedFields is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1',
      payloads: [{ id: 'pal1', createdTime: '2023-01-01T00:00:00.000Z', baseTransactionNumber: 1, tableId: 'tbl1', changes: [{ id: 'rec1' }] }]
    } as unknown as AirtableWebhookPayload, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })).rejects.toThrow('Missing required field: changedFields in change')
  })

  it('throws on non-2xx Discord response with status and endpoint', async () => {
