    }, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })).rejects.toThrow('Discord webhook request failed: 401 Unauthorized at https://discord.com/api/webhooks/id/token?wait=true')

    expect(calls).toHaveLength(1)
  })

  it('handles multiple changes across multiple payloads', async () => {
    const responses = [
      jsonResponse({ id: 'msg-1' }, 200),
      jsonResponse({ id: 'msg-2' }, 200),
      jsonResponse({ id: 'msg-3' }, 200)
    ]
    let callIndex = 0
    const { fetch, calls } = fakeFetch(() => responses[callIndex++])

    const payload: AirtableWebhookPayload = {
      baseId: 'app1',
      tableId: 'tbl1',
      webhookId: 'wh1',
      payloads: [
        {
          id: 'pal1',
          createdTime: '2023-01-01T00:00:00.000Z',
          baseTransactionNumber: 1,
          tableId: 'tbl1',
          changes: [
            { id: 'rec1', changedFields: { A: '1' } },
            { id: 'rec2', changedFields: { B: '2' } }
          ]
        },
        {
          id: 'pal2',
          createdTime: '2023-01-01T00:00:01.000Z',
          baseTransactionNumber: 2,
          tableId: 'tbl1',
          changes: [
            { id: 'rec3', changedFields: { C: '3' } }
          ]
        }
      ]
    }

    const result = await handle(payload, { discordWebhookId: 'id', discordWebhookToken: 'token', fetch })

    expect(result.messageIds).toEqual(['msg-1', 'msg-2', 'msg-3'])
    expect(calls).toHaveLength(3)
    expect(calls[0].json).toEqual({
      content: 'New Airtable record: rec1',
      embeds: [{ title: '2023-01-01T00:00:00.000Z', description: 'A: 1', color: 5763719 }]
    })
    expect(calls[1].json).toEqual({
      content: 'New Airtable record: rec2',
      embeds: [{ title: '2023-01-01T00:00:00.000Z', description: 'B: 2', color: 5763719 }]
    })
    expect(calls[2].json).toEqual({
